module.exports = "import React, { useState } from 'react';\nimport {\n  EuiDragDropContext,\n  EuiDraggable,\n  EuiDroppable,\n  EuiButtonIcon,\n  EuiPanel,\n} from '../../../../src/components';\n\nimport {\n  euiDragDropMove,\n  euiDragDropReorder,\n} from '../../../../src/components/drag_and_drop';\n\nimport { makeList } from './helper';\n\nexport default () => {\n  const [list, setList] = useState([1, 2]);\n  const [list1, setList1] = useState(makeList(3));\n  const [list2, setList2] = useState(makeList(3, 4));\n  const lists = {\n    COMPLEX_DROPPABLE_PARENT: list,\n    COMPLEX_DROPPABLE_AREA_1: list1,\n    COMPLEX_DROPPABLE_AREA_2: list2,\n  };\n  const actions = {\n    COMPLEX_DROPPABLE_PARENT: setList,\n    COMPLEX_DROPPABLE_AREA_1: setList1,\n    COMPLEX_DROPPABLE_AREA_2: setList2,\n  };\n  const onDragEnd = ({ source, destination }) => {\n    if (source && destination) {\n      if (source.droppableId === destination.droppableId) {\n        const items = euiDragDropReorder(\n          lists[destination.droppableId],\n          source.index,\n          destination.index\n        );\n\n        actions[destination.droppableId](items);\n      } else {\n        const sourceId = source.droppableId;\n        const destinationId = destination.droppableId;\n        const result = euiDragDropMove(\n          lists[sourceId],\n          lists[destinationId],\n          source,\n          destination\n        );\n\n        actions[sourceId](result[sourceId]);\n        actions[destinationId](result[destinationId]);\n      }\n    }\n  };\n  return (\n    <EuiDragDropContext onDragEnd={onDragEnd}>\n      <EuiDroppable\n        droppableId=\"COMPLEX_DROPPABLE_PARENT\"\n        type=\"MACRO\"\n        direction=\"horizontal\"\n        withPanel\n        spacing=\"l\"\n        style={{ display: 'flex' }}>\n        {list.map((did, didx) => (\n          <EuiDraggable\n            key={did}\n            index={didx}\n            draggableId={`COMPLEX_DRAGGABLE_${did}`}\n            spacing=\"l\"\n            style={{ flex: '1 0 50%' }}\n            disableInteractiveElementBlocking // Allows button to be drag handle\n          >\n            {provided => (\n              <EuiPanel paddingSize=\"s\">\n                <EuiButtonIcon\n                  iconType=\"grab\"\n                  aria-label=\"Drag Handle\"\n                  {...provided.dragHandleProps}\n                />\n                <EuiDroppable\n                  droppableId={`COMPLEX_DROPPABLE_AREA_${did}`}\n                  type=\"MICRO\"\n                  spacing=\"m\"\n                  style={{ flex: '1 0 50%' }}>\n                  {lists[`COMPLEX_DROPPABLE_AREA_${did}`].map(\n                    ({ content, id }, idx) => (\n                      <EuiDraggable\n                        key={id}\n                        index={idx}\n                        draggableId={id}\n                        spacing=\"m\">\n                        <EuiPanel>{content}</EuiPanel>\n                      </EuiDraggable>\n                    )\n                  )}\n                </EuiDroppable>\n              </EuiPanel>\n            )}\n          </EuiDraggable>\n        ))}\n      </EuiDroppable>\n    </EuiDragDropContext>\n  );\n};\n"