module.exports = "import React, { Fragment, useState } from 'react';\n\nimport {\n  EuiButtonEmpty,\n  EuiButtonIcon,\n  EuiFieldText,\n  EuiIcon,\n  EuiIconTip,\n  EuiPopover,\n  EuiSpacer,\n  EuiSwitch,\n  EuiText,\n  EuiToolTip,\n} from '../../../../src/components';\n\nexport default () => {\n  const [isCompressed, setCompressed] = useState(false);\n  const [isDisabled, setDisabled] = useState(false);\n  const [isReadOnly, setReadOnly] = useState(false);\n\n  return (\n    <Fragment>\n      <EuiSwitch\n        label=\"compressed\"\n        checked={isCompressed}\n        onChange={e => setCompressed(e.target.checked)}\n      />\n      &emsp;\n      <EuiSwitch\n        label=\"disabled\"\n        checked={isDisabled}\n        onChange={e => setDisabled(e.target.checked)}\n      />\n      &emsp;\n      <EuiSwitch\n        label=\"readOnly\"\n        checked={isReadOnly}\n        onChange={e => setReadOnly(e.target.checked)}\n      />\n      <EuiSpacer />\n      <EuiFieldText\n        placeholder=\"String & text in a tooltip\"\n        prepend=\"String\"\n        append={\n          <EuiToolTip content=\"content\">\n            <EuiText size=\"s\">Tooltip</EuiText>\n          </EuiToolTip>\n        }\n        compressed={isCompressed}\n        disabled={isDisabled}\n        readOnly={isReadOnly}\n      />\n      <EuiSpacer />\n      <EuiFieldText\n        placeholder=\"XS empty button in a popover & tooltip\"\n        prepend={\n          <EuiPopover\n            button={\n              <EuiButtonEmpty size=\"xs\" iconType=\"arrowDown\" iconSide=\"right\">\n                Popover\n              </EuiButtonEmpty>\n            }\n            closePopover={() => {}}\n          />\n        }\n        append={\n          <EuiToolTip content=\"content\">\n            <EuiButtonEmpty size=\"xs\">Tooltip</EuiButtonEmpty>\n          </EuiToolTip>\n        }\n        compressed={isCompressed}\n        disabled={isDisabled}\n        readOnly={isReadOnly}\n      />\n      <EuiSpacer />\n      <EuiFieldText\n        placeholder=\"XS empty buttons with icons\"\n        prepend={\n          <EuiButtonEmpty size=\"xs\" iconType=\"arrowDown\" iconSide=\"right\">\n            <EuiIcon type=\"calendar\" />\n          </EuiButtonEmpty>\n        }\n        append={\n          <EuiButtonEmpty size=\"xs\" iconType=\"gear\">\n            Tooltip\n          </EuiButtonEmpty>\n        }\n        compressed={isCompressed}\n        disabled={isDisabled}\n        readOnly={isReadOnly}\n      />\n      <EuiSpacer />\n      <EuiFieldText\n        placeholder=\"Icon & button icon\"\n        prepend={<EuiIcon type=\"vector\" />}\n        append={<EuiButtonIcon iconType=\"gear\" aria-label=\"Gear this\" />}\n        compressed={isCompressed}\n        disabled={isDisabled}\n        readOnly={isReadOnly}\n      />\n      <EuiSpacer />\n      <EuiFieldText\n        placeholder=\"Icons in buttons and popovers and tooltips\"\n        prepend={[\n          <EuiIcon type=\"vector\" />,\n          <EuiButtonIcon iconType=\"gear\" aria-label=\"Gear this\" />,\n        ]}\n        append={[\n          <EuiPopover\n            button={<EuiButtonIcon iconType=\"gear\" aria-label=\"Gear this\" />}\n            closePopover={() => {}}\n          />,\n          <EuiIconTip content=\"content\" />,\n        ]}\n        compressed={isCompressed}\n        disabled={isDisabled}\n        readOnly={isReadOnly}\n      />\n      <EuiSpacer />\n      <EuiFieldText\n        placeholder=\"Icon button in popover & tooltip\"\n        append={\n          <EuiPopover\n            button={<EuiButtonIcon iconType=\"arrowDown\" aria-label=\"Popover\" />}\n            closePopover={() => {}}\n          />\n        }\n        prepend={\n          <EuiToolTip content=\"content\">\n            <EuiButtonIcon iconType=\"gear\" aria-label=\"Gear this\" />\n          </EuiToolTip>\n        }\n        compressed={isCompressed}\n        disabled={isDisabled}\n        readOnly={isReadOnly}\n      />\n      <EuiSpacer />\n      <EuiFieldText\n        placeholder=\"Icon and string & string and icon button\"\n        prepend={[<EuiIcon type=\"vector\" />, 'String']}\n        append={[\n          'String',\n          <EuiButtonIcon iconType=\"gear\" aria-label=\"Gear this\" />,\n        ]}\n        compressed={isCompressed}\n        disabled={isDisabled}\n        readOnly={isReadOnly}\n      />\n      <EuiSpacer />\n      <EuiFieldText\n        placeholder=\"String and button icon in tooltip & button icon in popover and string \"\n        prepend={[\n          'String',\n          <EuiToolTip content=\"content\">\n            <EuiButtonIcon iconType=\"gear\" aria-label=\"Gear this\" />\n          </EuiToolTip>,\n        ]}\n        append={[\n          <EuiPopover\n            button={<EuiButtonIcon iconType=\"gear\" aria-label=\"Gear this\" />}\n            closePopover={() => {}}\n          />,\n          'String',\n        ]}\n        compressed={isCompressed}\n        disabled={isDisabled}\n        readOnly={isReadOnly}\n      />\n    </Fragment>\n  );\n};\n"