module.exports = "import React, { Component, Fragment } from 'react';\n\nimport { EuiSwitch, EuiSpacer } from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      checked: false,\n    };\n  }\n\n  onChange = e => {\n    this.setState({\n      checked: e.target.checked,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiSwitch\n          label=\"I am a switch\"\n          checked={this.state.checked}\n          onChange={this.onChange}\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiSwitch\n          label=\"I am a disabled switch\"\n          checked={this.state.checked}\n          onChange={this.onChange}\n          disabled\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiSwitch\n          label=\"I am a compressed switch\"\n          checked={this.state.checked}\n          onChange={this.onChange}\n          compressed\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiSwitch\n          label=\"I am a compressed, disabled switch\"\n          checked={this.state.checked}\n          onChange={this.onChange}\n          compressed\n          disabled\n        />\n      </Fragment>\n    );\n  }\n}\n"