module.exports = "import React, { useState } from 'react';\nimport {\n  EuiDragDropContext,\n  EuiDraggable,\n  EuiDroppable,\n  EuiPanel,\n} from '../../../../src/components';\n\nimport { euiDragDropReorder } from '../../../../src/components/drag_and_drop';\n\nimport { makeList } from './helper';\n\nexport default () => {\n  const [list, setList] = useState(makeList(3));\n  const onDragEnd = ({ source, destination }) => {\n    if (source && destination) {\n      const items = euiDragDropReorder(list, source.index, destination.index);\n\n      setList(items);\n    }\n  };\n  return (\n    <EuiDragDropContext onDragEnd={onDragEnd}>\n      <EuiDroppable droppableId=\"DROPPABLE_AREA\" spacing=\"m\" withPanel>\n        {list.map(({ content, id }, idx) => (\n          <EuiDraggable spacing=\"m\" key={id} index={idx} draggableId={id}>\n            {(provided, state) => (\n              <EuiPanel hasShadow={state.isDragging}>\n                {content}\n                {state.isDragging && ' ✨'}\n              </EuiPanel>\n            )}\n          </EuiDraggable>\n        ))}\n      </EuiDroppable>\n    </EuiDragDropContext>\n  );\n};\n"