module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiSelectable,\n  EuiSwitch,\n  EuiSelectableMessage,\n  EuiSpacer,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      useCustomMessage: false,\n      isLoading: false,\n    };\n  }\n\n  onSwitch = e => {\n    this.setState({\n      useCustomMessage: e.target.checked,\n    });\n  };\n\n  onLoading = e => {\n    this.setState({\n      isLoading: e.target.checked,\n    });\n  };\n\n  render() {\n    const { useCustomMessage, isLoading } = this.state;\n\n    const customMessage = (\n      <EuiSelectableMessage>You have no spice</EuiSelectableMessage>\n    );\n\n    return (\n      <Fragment>\n        <EuiSwitch\n          label=\"Custom message\"\n          onChange={this.onSwitch}\n          checked={!isLoading && useCustomMessage}\n          disabled={isLoading}\n        />\n        &emsp;\n        <EuiSwitch\n          label=\"Show loading\"\n          onChange={this.onLoading}\n          checked={isLoading}\n        />\n        <EuiSpacer />\n        <EuiSelectable\n          options={[]}\n          style={{ width: 200 }}\n          isLoading={isLoading}>\n          {list => (useCustomMessage && !isLoading ? customMessage : list)}\n        </EuiSelectable>\n      </Fragment>\n    );\n  }\n}\n"